-- Generated by scripts/apply_player_display_names_roster_height.R from the
-- live definition of basketball_test.player_display_names_v (2026-11-12):
-- height_m / position_en fall back to basket.co.il's team-page roster.

CREATE OR REPLACE VIEW basketball_test.player_display_names_v AS
 WITH roster AS (
         SELECT fr.game_id,
            fr.game_year,
            fr.team_id,
            fr.player_id,
            max(NULLIF(btrim(concat_ws(' '::text, fr.firstnamelocal, fr.lastnamelocal)), ''::text)) AS name_he
           FROM basketball_test.full_rosters fr
          WHERE fr.player_id IS NOT NULL
          GROUP BY fr.game_id, fr.game_year, fr.team_id, fr.player_id
        ), per_game AS (
         SELECT r.game_year,
            r.team_id,
            r.source_player_id AS player_id,
            r.identity_id,
            r.resolution_scope,
            r.display_name,
            ro.name_he
           FROM basketball_test.resolved_player_identity_v r
             JOIN roster ro ON ro.game_id = r.game_id AND ro.team_id = r.team_id AND ro.player_id = r.source_player_id
        ), pairs AS (
         SELECT per_game.game_year,
            per_game.team_id,
            per_game.player_id,
            count(DISTINCT per_game.identity_id) AS identities,
            min(per_game.identity_id) AS identity_id,
            bool_or(per_game.resolution_scope <> 'source'::text) AS in_dictionary
           FROM per_game
          GROUP BY per_game.game_year, per_game.team_id, per_game.player_id
        ), spelling_en AS (
         SELECT DISTINCT ON (s.game_year, s.team_id, s.player_id) s.game_year,
            s.team_id,
            s.player_id,
            s.display_name
           FROM ( SELECT per_game.game_year,
                    per_game.team_id,
                    per_game.player_id,
                    per_game.display_name,
                    count(*) AS games
                   FROM per_game
                  WHERE per_game.display_name IS NOT NULL
                  GROUP BY per_game.game_year, per_game.team_id, per_game.player_id, per_game.display_name) s
          ORDER BY s.game_year, s.team_id, s.player_id, s.games DESC, s.display_name
        ), spelling_he AS (
         SELECT DISTINCT ON (s.game_year, s.team_id, s.player_id) s.game_year,
            s.team_id,
            s.player_id,
            s.name_he
           FROM ( SELECT per_game.game_year,
                    per_game.team_id,
                    per_game.player_id,
                    per_game.name_he,
                    count(*) AS games
                   FROM per_game
                  WHERE per_game.name_he IS NOT NULL
                  GROUP BY per_game.game_year, per_game.team_id, per_game.player_id, per_game.name_he) s
          ORDER BY s.game_year, s.team_id, s.player_id, s.games DESC, s.name_he
        ), basket AS (
         SELECT b.game_year,
            d.team_id_rosters AS team_id,
            b.identity_id,
            min(NULLIF(btrim(b.player_name_en), ''::text)) AS name_en,
            min(NULLIF(btrim(b.player_name), ''::text)) AS name_he,
            max(b.height_m) AS height_m,
            min(b.position_en) AS position_en
           FROM basketball_test.basket_player_season b
             JOIN basketball_test.schedule_team_dict d ON d.game_year = b.game_year AND d.team_name_basket = b.basket_team_name
          WHERE b.identity_match_status = 'verified'::text
          GROUP BY b.game_year, d.team_id_rosters, b.identity_id
        ), roster_size AS (
         SELECT r.game_year,
            d.team_id_rosters AS team_id,
            r.identity_id,
            max(r.height_m) AS height_m,
            min(r.position_en) AS position_en
           FROM basketball_test.basket_player_roster r
             JOIN basketball_test.schedule_team_dict d ON d.game_year = r.game_year AND d.team_name_basket = r.basket_team_name
          WHERE r.identity_match_status = 'verified'::text
          GROUP BY r.game_year, d.team_id_rosters, r.identity_id
        )
 SELECT p.game_year,
    p.team_id,
    p.player_id,
        CASE
            WHEN p.identities = 1 THEN p.identity_id
            ELSE NULL::bigint
        END AS identity_id,
        CASE
            WHEN p.identities = 1 THEN COALESCE(upper(bk.name_en), en.display_name)
            ELSE NULL::text
        END AS display_name,
        CASE
            WHEN p.identities = 1 THEN COALESCE(bk.name_he, NULLIF(btrim(concat_ws(' '::text, pi.first_name_local, pi.last_name_local)), ''::text), he.name_he)
            ELSE NULL::text
        END AS display_name_he,
        CASE
            WHEN p.identities > 1 THEN 'reused_id'::text
            WHEN bk.name_en IS NOT NULL THEN 'basket'::text
            WHEN p.in_dictionary THEN 'dictionary'::text
            ELSE 'roster'::text
        END AS name_source,
        CASE
            WHEN p.identities = 1 THEN COALESCE(bk.height_m, rs.height_m) ELSE NULL::numeric END AS height_m,
        CASE
            WHEN p.identities = 1 THEN COALESCE(bk.position_en, rs.position_en) ELSE NULL::text END AS position_en
   FROM pairs p
     LEFT JOIN spelling_en en USING (game_year, team_id, player_id)
     LEFT JOIN spelling_he he USING (game_year, team_id, player_id)
     LEFT JOIN basket bk ON p.identities = 1 AND bk.game_year = p.game_year AND bk.team_id = p.team_id AND bk.identity_id = p.identity_id
     LEFT JOIN roster_size rs ON p.identities = 1 AND rs.game_year = p.game_year AND rs.team_id = p.team_id AND rs.identity_id = p.identity_id
     LEFT JOIN basketball_test.player_identities pi ON p.identities = 1 AND p.in_dictionary AND pi.identity_id = p.identity_id;

